<script setup lang="ts">
import {can} from './session'
import {ref,reactive,onMounted} from 'vue'
import {api,session} from './session'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useTableWidths} from './tableWidths'
const widths=useTableWidths('SupplierPanel'),rows=ref<any[]>([]),q=ref(''),page=ref(1),pageSize=ref(25),total=ref(0),busy=ref(false),error=ref(''),dialog=ref(false),id=ref<number>(),form=reactive<any>({})
const purchase:any={online:'线上',offline:'线下'},settlement:any={'1688':'1688',credit:'账期'}
async function load(){busy.value=true;try{const d=await api('/product-data/suppliers?'+new URLSearchParams({q:q.value,page:String(page.value),page_size:String(pageSize.value)}));rows.value=d.rows;total.value=d.total;error.value=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function edit(r?:any){id.value=r?.id;Object.assign(form,{name:r?.name||'',shop_url:r?.shop_url||'',purchase_method:r?.purchase_method||'',settlement_method:r?.settlement_method||'',shipping_days:r?.shipping_days??null,revision:r?.revision});dialog.value=true}
async function save(){busy.value=true;try{await api('/product-data/suppliers'+(id.value?'/'+id.value:''),form);dialog.value=false;await load();ElMessage.success('供应商已保存')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function remove(r:any){try{await ElMessageBox.confirm('确定删除供应商「'+r.name+'」？','删除供应商');await api('/product-data/suppliers/'+r.id+'/delete',{revision:r.revision});await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
onMounted(load)
</script>
<template><section class="supplier-panel"><div class="product-tools"><el-input v-model="q" placeholder="搜索供应商名称" clearable style="width:260px" @keyup.enter="page=1;load()"/><el-button type="primary" @click="page=1;load()">查询</el-button><el-button @click="q='';page=1;load()">重置</el-button><el-button v-if="can('products.suppliers','operate')" type="primary" @click="edit()">新增供应商</el-button><TableReset table-key="SupplierPanel/list"/></div><el-alert v-if="error" :title="error" type="error"/><template v-if="true"><el-table :data="rows" v-loading="busy" border data-width-key="SupplierPanel/list" @header-dragend="(w:number,_:number,c:any)=>widths.resize('list',w,c)"><el-table-column prop="name" label="供应商名称" column-key="name" :width="widths.width('list','name',300)"/><el-table-column label="1688店铺链接" column-key="url" :width="widths.width('list','url',330)"><template #default="{row}"><a v-if="row.shop_url" :href="row.shop_url" target="_blank" rel="noopener noreferrer">{{row.shop_url}}</a><span v-else>—</span></template></el-table-column><el-table-column label="采购方式" column-key="purchase" :width="widths.width('list','purchase',150)"><template #default="{row}">{{purchase[row.purchase_method]||'—'}}</template></el-table-column><el-table-column label="结算方式" column-key="settlement" :width="widths.width('list','settlement',150)"><template #default="{row}">{{settlement[row.settlement_method]||'—'}}</template></el-table-column><el-table-column label="发货周期" column-key="shipping_days" :width="widths.width('list','shipping_days',120)" align="center"><template #default="{row}">{{row.shipping_days ? row.shipping_days+'天' : '未配置'}}</template></el-table-column><el-table-column v-if="can('products.suppliers','operate')" label="操作" fixed="right" min-width="140"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></template><AppPagination v-model:current-page="page" :total="total" @change="load" v-model:page-size="pageSize"/><el-dialog v-model="dialog" :title="id?'编辑供应商':'新增供应商'" width="580px"><el-form label-position="top"><el-form-item label="供应商名称" required><el-input v-model="form.name" maxlength="500"/></el-form-item><el-form-item label="1688店铺链接（选填）"><el-input v-model="form.shop_url" placeholder="https://…"/></el-form-item><el-form-item label="采购方式（选填）"><el-select v-model="form.purchase_method" clearable :value-on-clear="''"><el-option value="online" label="线上"/><el-option value="offline" label="线下"/></el-select></el-form-item><el-form-item label="结算方式（选填）"><el-select v-model="form.settlement_method" clearable :value-on-clear="''"><el-option value="1688" label="1688"/><el-option value="credit" label="账期"/></el-select></el-form-item><el-form-item label="发货周期"><el-select v-model="form.shipping_days" aria-label="供应商发货周期" placeholder="选择发货周期" clearable :value-on-clear="null"><el-option v-for="n in [1,3,5,7,14,30]" :key="n" :value="n" :label="n+'天'"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.product-tools{display:flex;gap:10px;align-items:center;padding:12px 0}.supplier-panel .el-pagination{margin:14px 0}.supplier-panel a{color:#227660}</style>
